#!/usr/bin/env python3
"""Validate storyboard JSON generated by the novel-3d-animation-style-v1 skill."""

from __future__ import annotations

import argparse
import json
import re
import sys
from decimal import Decimal
from pathlib import Path
from typing import Any, Dict, List, Mapping, Optional, Sequence, Set, Tuple

try:
    from .validate_adapted_script import (
        _semantic_chars,
        _spoken_body,
        validate_adapted_script,
    )
except ImportError:
    from validate_adapted_script import (  # type: ignore
        _semantic_chars,
        _spoken_body,
        validate_adapted_script,
    )


TOP_LEVEL_FIELDS = ["character", "scene", "item", "storyboard"]
STORYBOARD_FIELDS = ["name", "duration", "prompt", "character", "scene", "item"]
ASSET_FIELDS = ["name", "prompt"]
STYLE_LINE = "次世代CG动画，高质量虚幻5渲染，戏剧性的光照。写实细腻的人物表演，不要出现卡通化的面部表情，【禁止出现字幕】【禁止加bgm】"

ASSET_LABELS = {
    "character": "角色",
    "scene": "场景",
    "item": "物品",
}
TOKEN_TO_FIELD = {
    "角色": "character",
    "场景": "scene",
    "物品": "item",
}

SHOT_LINE_RE = re.compile(r"^c(\d{2}),(\d+(?:\.5)?)s,")
TOKEN_RE = re.compile(r"@\[(角色|场景|物品)-([^\]]+)\]")
VOICE_RE = re.compile(
    r"(?:"
    r"@\[角色-(?P<named>[^\]]+)\](?P<named_mode>[（(][^）)]*[）)])?"
    r"|"
    r"(?P<anonymous>旁白|OV|机械的电子音女声|广播声|电话声|录音声)"
    r"(?P<anonymous_mode>[（(][^）)]*[）)])?"
    r")[：:]\s*[“\"](?P<body>.*?)[”\"]"
)
MODE_RE = re.compile(r"[（(]([^）)]*)[）)]\s*$")


def load_json(path: Path) -> Tuple[Optional[Any], List[str]]:
    """Load UTF-8 JSON and return all file-level errors without raising."""
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        return None, [f"无法读取 JSON 文件 {path}: {exc}"]

    try:
        return json.loads(text), []
    except json.JSONDecodeError as exc:
        return None, [f"JSON 解析失败（第 {exc.lineno} 行第 {exc.colno} 列）: {exc.msg}"]


def _is_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _voice_kind(mode: str) -> str:
    upper = mode.upper()
    if "OS" in upper or "内心" in mode:
        return "os"
    if "VO" in upper:
        return "vo"
    if "OV" in upper or "旁白" in mode or "画外音" in mode:
        return "narration"
    return "dialogue"


def _canonical_speaker(speaker: str) -> str:
    stripped = speaker.strip().lstrip("▲+")
    return "旁白" if stripped.upper() == "OV" else stripped


def _adapted_voice(text: str) -> Optional[Tuple[str, str, str]]:
    parts = re.split(r"[：:]", text, maxsplit=1)
    if len(parts) != 2:
        return None
    label = parts[0].strip()
    mode_match = MODE_RE.search(label)
    mode = mode_match.group(1).strip() if mode_match else ""
    speaker = label[: mode_match.start()].strip() if mode_match else label
    if speaker.upper().lstrip("▲+") == "OV":
        mode = mode or "OV"
    return _canonical_speaker(speaker), _voice_kind(mode), _spoken_body(text)


def _storyboard_voices(data: Mapping[str, Any]) -> List[Tuple[str, str, str]]:
    voices: List[Tuple[str, str, str]] = []
    storyboards = data.get("storyboard")
    if not isinstance(storyboards, list):
        return voices
    for shot in storyboards:
        if not isinstance(shot, dict) or not isinstance(shot.get("prompt"), str):
            continue
        for match in VOICE_RE.finditer(shot["prompt"]):
            speaker = match.group("named") or match.group("anonymous") or ""
            mode = match.group("named_mode") or match.group("anonymous_mode") or ""
            voices.append(
                (_canonical_speaker(speaker), _voice_kind(mode), match.group("body"))
            )
    return voices


def _validate_voice_ledger(
    data: Mapping[str, Any], adapted_script: Any, errors: List[str]
) -> None:
    adapted_errors = validate_adapted_script(adapted_script)
    errors.extend(f"adapted_script: {error}" for error in adapted_errors)
    if adapted_errors or not isinstance(adapted_script, dict):
        return

    line_records = adapted_script.get("scriptLines")
    if not isinstance(line_records, list):
        return
    ledger: List[Tuple[str, str, str]] = []
    for record in line_records:
        if not isinstance(record, dict) or not isinstance(record.get("text"), str):
            continue
        voice = _adapted_voice(record["text"])
        if voice is not None:
            ledger.append(voice)

    actual = _storyboard_voices(data)
    actual_index = 0
    for ledger_index, (expected_speaker, expected_kind, expected_body) in enumerate(
        ledger, start=1
    ):
        expected_chars = _semantic_chars(expected_body)
        combined = ""
        while combined != expected_chars:
            if actual_index >= len(actual):
                errors.append(
                    f"语音账本未完整覆盖: adapted_script 第 {ledger_index} 项未出现在分镜中"
                )
                return
            actual_speaker, actual_kind, actual_body = actual[actual_index]
            if actual_speaker != expected_speaker or actual_kind != expected_kind:
                errors.append(
                    "说话人与 adapted_script 不一致: "
                    f"第 {ledger_index} 项应为 {expected_speaker}，实际为 {actual_speaker}"
                )
                return
            candidate = combined + _semantic_chars(actual_body)
            if not expected_chars.startswith(candidate):
                errors.append(
                    f"语音正文与 adapted_script 不一致: 第 {ledger_index} 项正文被改写、增删或换序"
                )
                return
            combined = candidate
            actual_index += 1

    if actual_index < len(actual):
        errors.append("输出包含 adapted_script 不存在的新增语音")


def _validate_assets(
    data: Mapping[str, Any],
    errors: List[str],
) -> Dict[str, Set[str]]:
    declared: Dict[str, Set[str]] = {field: set() for field in ASSET_LABELS}

    for field, label in ASSET_LABELS.items():
        assets = data.get(field)
        if not isinstance(assets, list):
            errors.append(f"顶层 {field} 必须是数组")
            continue

        for index, asset in enumerate(assets):
            location = f"{field}[{index}]"
            if not isinstance(asset, dict):
                errors.append(f"{location} 必须是对象")
                continue
            if list(asset.keys()) != ASSET_FIELDS:
                errors.append(
                    f"{location} 字段顺序必须为 {', '.join(ASSET_FIELDS)}"
                )

            name = asset.get("name")
            prompt = asset.get("prompt")
            if not isinstance(name, str) or not name.strip():
                errors.append(f"{location}.name 必须是非空字符串")
            elif name in declared[field]:
                errors.append(f"{label}资产名称重复: {name}")
            else:
                declared[field].add(name)

            if not isinstance(prompt, str) or not prompt.strip():
                errors.append(f"{location}.prompt 必须是非空字符串")

    return declared


def _validate_reference_array(
    shot: Mapping[str, Any],
    field: str,
    index: int,
    declared: Mapping[str, Set[str]],
    errors: List[str],
) -> Optional[Set[str]]:
    values = shot.get(field)
    if not isinstance(values, list):
        errors.append(f"storyboard[{index}].{field} 必须是数组")
        return None
    if any(not isinstance(value, str) or not value for value in values):
        errors.append(f"storyboard[{index}].{field} 只能包含非空字符串")
        return None

    value_set = set(values)
    if len(value_set) != len(values):
        errors.append(f"storyboard[{index}].{field} 不得包含重复名称")

    label = ASSET_LABELS[field]
    for value in values:
        if value not in declared[field]:
            errors.append(
                f"storyboard[{index}] {label}引用“{value}”未在顶层资产中声明"
            )
    return value_set


def _parse_shot_lines(prompt: str, index: int, errors: List[str]) -> List[str]:
    lines = prompt.splitlines()
    if not lines or lines[0] != STYLE_LINE:
        errors.append(f"storyboard[{index}].prompt 首行必须是固定风格串")

    shot_lines = lines[1:] if lines else []
    if not shot_lines:
        errors.append(f"storyboard[{index}].prompt 至少需要一个 cNN 子镜头")
        return []

    matches = []
    for line_number, line in enumerate(shot_lines, start=2):
        match = SHOT_LINE_RE.match(line)
        if match is None:
            errors.append(
                f"storyboard[{index}].prompt 第 {line_number} 行必须以 cNN,Ns, 开头"
            )
        matches.append(match)

    valid_matches = [match for match in matches if match is not None]
    actual_numbers = [int(match.group(1)) for match in valid_matches]
    expected_numbers = list(range(1, len(shot_lines) + 1))
    if len(valid_matches) != len(shot_lines) or actual_numbers != expected_numbers:
        errors.append(f"storyboard[{index}] cNN 编号必须从 c01 连续递增")

    return shot_lines


def validate_storyboard(
    data: Any, duration_sec: int, adapted_script: Any = None
) -> List[str]:
    """Return every structural and deterministic semantic validation error."""
    errors: List[str] = []
    if not _is_int(duration_sec) or duration_sec < 4:
        return ["duration_sec 必须是大于等于 4 的整数"]
    if not isinstance(data, dict):
        return ["JSON 顶层必须是对象"]

    if list(data.keys()) != TOP_LEVEL_FIELDS:
        errors.append(f"顶层字段顺序必须为 {', '.join(TOP_LEVEL_FIELDS)}")

    declared = _validate_assets(data, errors)
    used_globally: Dict[str, Set[str]] = {field: set() for field in ASSET_LABELS}

    storyboards = data.get("storyboard")
    if not isinstance(storyboards, list):
        errors.append("顶层 storyboard 必须是数组")
        return errors
    if not storyboards:
        errors.append("顶层 storyboard 不得为空")
        return errors

    seen_storyboard_names: Set[str] = set()
    for index, shot in enumerate(storyboards):
        location = f"storyboard[{index}]"
        if not isinstance(shot, dict):
            errors.append(f"{location} 必须是对象")
            continue
        if list(shot.keys()) != STORYBOARD_FIELDS:
            errors.append(
                f"{location} 分镜字段顺序必须为 {', '.join(STORYBOARD_FIELDS)}"
            )

        name = shot.get("name")
        if not isinstance(name, str) or not name:
            errors.append(f"{location}.name 必须是非空字符串")
        elif len(name) > 15:
            errors.append(f"{location}.name 不得超过 15 字")
        elif name in seen_storyboard_names:
            errors.append(f"{location}.name 分镜名称重复: {name}")
        else:
            seen_storyboard_names.add(name)

        duration = shot.get("duration")
        if not _is_int(duration):
            errors.append(f"{location}.duration 必须是整数")
        elif not 4 <= duration <= duration_sec:
            position = "非末镜" if index < len(storyboards) - 1 else "末镜"
            errors.append(
                f"{location} {position} duration 必须在 4..{duration_sec} 范围内"
            )

        prompt = shot.get("prompt")
        if not isinstance(prompt, str):
            errors.append(f"{location}.prompt 必须是字符串")
            shot_lines: List[str] = []
        else:
            shot_lines = _parse_shot_lines(prompt, index, errors)
            durations = []
            for line in shot_lines:
                match = SHOT_LINE_RE.match(line)
                if match is not None:
                    durations.append(Decimal(match.group(2)))
            if _is_int(duration) and sum(durations) != Decimal(duration):
                errors.append(
                    f"{location} cNN 秒数之和 {sum(durations)} 不等于 duration {duration}"
                )
            if shot_lines and "不出现任何文字字幕" not in shot_lines[-1]:
                errors.append(
                    f"{location} 最后一个子镜头必须包含“不出现任何文字字幕”"
                )

        reference_sets: Dict[str, Optional[Set[str]]] = {}
        for field in ASSET_LABELS:
            reference_sets[field] = _validate_reference_array(
                shot, field, index, declared, errors
            )

        tokens_by_field: Dict[str, Set[str]] = {
            field: set() for field in ASSET_LABELS
        }
        if isinstance(prompt, str):
            for token_type, token_name in TOKEN_RE.findall(prompt):
                field = TOKEN_TO_FIELD[token_type]
                tokens_by_field[field].add(token_name)

        for field, label in ASSET_LABELS.items():
            token_names = tokens_by_field[field]
            references = reference_sets[field]
            used_globally[field].update(token_names)
            for token_name in token_names:
                if token_name not in declared[field]:
                    errors.append(
                        f"{location} {label}引用“{token_name}”未在顶层资产中声明"
                    )
            if references is not None and references != token_names:
                missing = sorted(token_names - references)
                extra = sorted(references - token_names)
                details = []
                if missing:
                    details.append(f"数组缺少 {missing}")
                if extra:
                    details.append(f"数组多出 {extra}")
                errors.append(
                    f"{location}.{field} 引用数组与 prompt token 不闭环: "
                    + "；".join(details)
                )

    for field, label in ASSET_LABELS.items():
        for unused in sorted(declared[field] - used_globally[field]):
            errors.append(f"顶层{label}资产“{unused}”未被任何分镜引用")

    if adapted_script is not None:
        _validate_voice_ledger(data, adapted_script, errors)

    return errors


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("json_file", type=Path, help="待校验的 UTF-8 JSON 文件")
    parser.add_argument(
        "--duration-sec",
        type=int,
        required=True,
        help="分镜主切割时长上限（秒；每个分镜为 4..该值）",
    )
    parser.add_argument(
        "--adapted-script",
        type=Path,
        required=True,
        help="已通过阶段 0 校验的 adapted_script.json，用于确定性语义对账",
    )
    return parser


def main(argv: Optional[Sequence[str]] = None) -> int:
    args = build_parser().parse_args(argv)
    data, load_errors = load_json(args.json_file)
    adapted_script, adapted_load_errors = load_json(args.adapted_script)
    load_errors.extend(
        f"adapted_script: {error}" for error in adapted_load_errors
    )
    if load_errors:
        for error in load_errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 2

    errors = validate_storyboard(data, args.duration_sec, adapted_script)
    if errors:
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1

    print("OK: storyboard JSON is valid")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
